import { getInspectorConfiguration } from '../core/settings.mjs';
import { copyRunSettings } from '../core/run-state.mjs';
import { normalizeThemeColor } from '../core/theme.mjs';
import { getTimerInspectorConfiguration, MIN_INTERVAL_SECONDS, MAX_INTERVAL_SECONDS } from '../core/timer-settings.mjs';

const FIELDS = new Set(['executable', 'argsText', 'cwd', 'themeColor']);
export const RUN_ACTION_UUID = 'git.renaudcerrato.deckforge.run';
export const TIMER_ACTION_UUID = 'git.renaudcerrato.deckforge.timer';
export const ONCE_ACTION_UUID = 'git.renaudcerrato.deckforge.once';
const SAFE_REASONS = new Set([
  'STATE_SAVE_FAILED', 'INVALID_SETTINGS', 'INVALID_EXECUTABLE', 'INVALID_CWD',
  'ARGS_TEXT_INVALID', 'ARGS_JSON_INVALID', 'ARGS_NOT_ARRAY', 'INVALID_ARGUMENT',
  'THEME_COLOR_INVALID', 'INTERVAL_INVALID', 'ACTION_ON_PRESS_INVALID',
]);

const TRACE_STAGES = new Set([
  'PICKER_CHANGED', 'PICKER_ACCEPTED', 'PICKER_REJECTED', 'EXECUTABLE_HYDRATE', 'EXECUTABLE_HYDRATE_APPLIED',
  'PI_CONNECT', 'PI_DISCONNECT', 'PI_SOCKET_OPEN', 'PI_SOCKET_CLOSED', 'PI_SOCKET_ERROR',
  'PI_HELLO_SENT', 'PI_CHALLENGE_RECEIVED', 'PI_CLAIM_SENT', 'PI_READY', 'PI_TIMEOUT',
  'PI_REPLY_RECEIVED', 'PI_REPLY_IGNORED', 'PI_REPLY_REJECTED', 'PI_HYDRATE', 'PI_HYDRATE_FAILED',
  'EDIT_ACCEPTED', 'EDIT_REJECTED', 'EDIT_QUEUED', 'EDIT_SENT', 'EDIT_SEND_FAILED',
  'EDIT_DROPPED_ON_CONNECT', 'PI_TRACE_DROPPED',
]);
const TRACE_PATHS = ['selection', 'previousExecutable', 'executable', 'cwd', 'currentExecutable', 'currentCwd'];
const TRACE_LABELS = ['context', 'payloadContext', 'inspectorId', 'replyInspectorId', 'requestType', 'reason', 'status', 'selectionType', 'selectionSource'];
const TRACE_NUMBERS = ['requestId', 'replyRequestId', 'traceId', 'version', 'count', 'executableVersion', 'cwdVersion', 'argsTextVersion'];
const TRACE_FLAGS = ['ready', 'open', 'pending', 'accepted'];
const TRACE_FIELDS = new Set(['executable', 'argsText', 'cwd', 'themeColor', 'other']);

function traceProperty(input, key) {
  try { return Object.getOwnPropertyDescriptor(input, key)?.value; } catch { return undefined; }
}

function connectionText(value) {
  if (typeof value !== 'string') return null;
  return value.replace(/[\u0000-\u001f\u007f-\u009f\u2028\u2029]/g,
    character => `\\u${character.charCodeAt(0).toString(16).padStart(4, '0')}`).slice(0, 256);
}

function connectionArgumentType(value) {
  return value === null ? 'null' : Array.isArray(value) ? 'array' : typeof value;
}

function boundedTraceText(value, maximum) {
  const suffix = ' [TRUNCATED]';
  const encoder = new TextEncoder();
  let bytes = 2;
  let result = '';
  for (const character of value) {
    const encoded = JSON.stringify(character).slice(1, -1)
      .replace(/[\u007f-\u009f\u2028\u2029]/g, item => `\\u${item.charCodeAt(0).toString(16).padStart(4, '0')}`);
    const size = encoder.encode(encoded).length;
    if (bytes + size > maximum - suffix.length) return result + suffix;
    result += character;
    bytes += size;
  }
  return result;
}

/** Bounded diagnostic DTO: authorized paths/correlation only, never args text or complete settings. */
export function makeInspectorTrace(stage, details = {}) {
  if (!TRACE_STAGES.has(stage)) return undefined;
  const result = { stage };
  try {
    for (const key of [...TRACE_PATHS, ...TRACE_LABELS]) {
      const value = traceProperty(details, key);
      if (typeof value === 'string') result[key] = boundedTraceText(value, TRACE_PATHS.includes(key) ? 4_096 : 256);
    }
    for (const key of TRACE_NUMBERS) {
      const value = traceProperty(details, key);
      if (Number.isSafeInteger(value) && value >= 0) result[key] = value;
    }
    for (const key of TRACE_FLAGS) {
      const value = traceProperty(details, key);
      if (typeof value === 'boolean') result[key] = value;
    }
    const fields = traceProperty(details, 'fields');
    if (Array.isArray(fields)) result.fields = [...new Set(fields.slice(0, 5).filter(value => TRACE_FIELDS.has(value)))];
  } catch { /* A failed diagnostic must not change the PI behavior. */ }
  return result;
}

/** One PI socket; only narrow configuration edits leave this bridge. */
export function createInspectorBridge({
  createSocket = url => new WebSocket(url),
  inspectorId = `${Date.now()}-${Math.random().toString(36).slice(2)}`,
  onSettings = () => {}, onError = () => {}, onStatus = () => {}, onTrace = () => {}, onConnectionState = () => {},
  delayMs = 200, timeoutMs = 15_000, setTimer = setTimeout, clearTimer = clearTimeout,
} = {}) {
  let socket;
  const inspectorIdPrefix = inspectorId;
  let connectionCount = 0;
  let connectionVersion = 0;
  let hasBoundContext = false;
  let bindingValid = false;
  let context;
  let action;
  let transportContext;
  let open = false;
  let ready = false;
  let requestId = 0;
  let latestRequest;
  let debounceTimer;
  let replyTimer;
  let pending = false;
  const versions = new Map();
  const acknowledged = new Map();
  const dirtyValues = new Map();
  const traceQueue = [];
  const traceBindings = new WeakMap();
  let traceScope;
  let traceId = 0;
  let droppedTraces = 0;
  let flushingTraces = false;
  let observingTrace = false;
  let observingConnection = false;
  const connection = {
    phase: 'WAITING_SDK_CALLBACK', callbackCount: 0, callbackArgCount: 0, callbackTypes: {},
    validation: 'NOT_RECEIVED', socketUrl: null, registrationUuid: null, registrationEvent: null,
    registrationSent: false, helloSent: false, challengeReceived: false, claimSent: false,
    lastError: null, lastClose: null,
  };

  /** Detached, read-only local observations; no socket/config action and no backend-log dependency. */
  function getConnectionState() {
    let socketReadyState = null;
    try { if ([0, 1, 2, 3].includes(socket?.readyState)) socketReadyState = socket.readyState; } catch {}
    return {
      ...connection, callbackTypes: { ...connection.callbackTypes },
      lastError: connection.lastError ? { ...connection.lastError } : null,
      lastClose: connection.lastClose ? { ...connection.lastClose } : null,
      socketCreated: Boolean(socket), socketReadyState, open, ready, pending, bindingValid,
      version: connectionVersion, inspectorId: connectionText(inspectorId),
      actionUuid: connectionText(action), context: connectionText(context),
      transportContext: connectionText(transportContext),
      latestRequestId: latestRequest?.id ?? requestId, latestRequestType: latestRequest?.type ?? null,
      latestRequestActive: latestRequest?.active ?? false,
    };
  }

  function observeConnection(phase) {
    if (phase) connection.phase = phase;
    if (observingConnection) return;
    observingConnection = true;
    try { void Promise.resolve(onConnectionState(getConnectionState())).catch(() => {}); } catch {}
    finally { observingConnection = false; }
  }

  function connectionError(reason) {
    connection.lastError = { reason, version: connectionVersion };
    observeConnection('ERROR');
  }

  function observeTrace(record) {
    if (observingTrace) return;
    observingTrace = true;
    try {
      const copy = { ...record };
      if (record.fields) copy.fields = [...record.fields];
      void Promise.resolve(onTrace(copy)).catch(() => {});
    } catch {}
    finally { observingTrace = false; }
  }

  function flushTraces() {
    if (!open || !socket || !context || !action || flushingTraces) return;
    flushingTraces = true;
    try {
      const budget = traceQueue.length;
      for (let index = 0; index < budget; index++) {
        const record = traceQueue[0];
        const binding = traceBindings.get(record);
        if (!binding || binding !== traceScope || binding.context !== context
          || (record.context && record.context !== binding.context)) { traceQueue.shift(); droppedTraces++; continue; }
        const payload = { ...record, context: binding.context, type: 'canvas:trace' };
        socket.send(JSON.stringify({ event: 'sendToPlugin', action, context: transportContext, payload }));
        traceQueue.shift();
      }
    } catch { /* Diagnostics do not change socket readiness, timers, edits, or UI error state. */ }
    finally { flushingTraces = false; }
  }

  function trace(stage, details = {}) {
    try {
      const bounded = makeInspectorTrace(stage, details);
      if (!bounded) return;
      const base = makeInspectorTrace(stage, {
        context, inspectorId, requestId: latestRequest?.id ?? requestId,
        traceId: ++traceId, version: connectionVersion, ready, open, pending,
        executableVersion: versions.get('executable') ?? 0,
        cwdVersion: versions.get('cwd') ?? 0, argsTextVersion: versions.get('argsText') ?? 0,
      });
      if (!base) return;
      const record = { ...base, ...bounded };
      if (traceScope) traceBindings.set(record, traceScope);
      observeTrace(record);
      if (traceQueue.length >= 32) { traceQueue.shift(); droppedTraces++; }
      traceQueue.push(record);
      flushTraces();
    } catch { /* Logging is observational only. */ }
  }

  function pendingTraceDetails() {
    return { fields: [...protectedFields()], executable: dirtyValues.get('executable'), cwd: dirtyValues.get('cwd') };
  }

  function failure(code = 'STATE_SAVE_FAILED') {
    onError(SAFE_REASONS.has(code) ? code : 'STATE_SAVE_FAILED');
    onStatus('error');
  }

  function protectedFields() {
    return new Set([...versions.keys()].filter(key => versions.get(key) !== (acknowledged.get(key) ?? 0)));
  }

  function hydrate(settings) {
    try {
      const project = bindingValid && action === TIMER_ACTION_UUID ? getTimerInspectorConfiguration : getInspectorConfiguration;
      const configuration = project(copyRunSettings(settings));
      const protectedKeys = protectedFields();
      const code = configuration.diagnosticCode;
      const field = code?.startsWith('ARGS_') || code === 'INVALID_ARGUMENT' ? 'argsText'
        : code === 'INVALID_EXECUTABLE' ? 'executable' : code === 'INVALID_CWD' ? 'cwd'
          : code === 'INTERVAL_INVALID' ? 'intervalSeconds'
            : code === 'ACTION_ON_PRESS_INVALID' ? 'actionOnPress' : undefined;
      if (field && protectedKeys.has(field)) delete configuration.diagnosticCode;
      trace('PI_HYDRATE', {
        executable: configuration.executable, cwd: configuration.cwd, fields: [...protectedKeys],
        reason: configuration.diagnosticCode ?? 'PROJECTED',
      });
      onSettings(configuration, protectedKeys);
      if (configuration.diagnosticCode) failure(configuration.diagnosticCode);
      return true;
    } catch {
      trace('PI_HYDRATE_FAILED', { reason: 'PROJECTION_FAILED' });
      failure();
      return false;
    }
  }

  function clearTimers() {
    if (debounceTimer !== undefined) clearTimer(debounceTimer);
    if (replyTimer !== undefined) clearTimer(replyTimer);
    debounceTimer = replyTimer = undefined;
  }

  function sendRequest(type, changes, token) {
    if (!open) return;
    if (replyTimer !== undefined) clearTimer(replyTimer);
    const id = ++requestId;
    latestRequest = { id, type, active: true, versions: new Map(versions), fields: Object.keys(changes ?? {}) };
    const version = connectionVersion;
    replyTimer = setTimer(() => {
      replyTimer = undefined;
      if (version === connectionVersion && latestRequest?.id === id) {
        latestRequest.active = false;
        connectionError('REPLY_TIMEOUT');
        trace('PI_TIMEOUT', { requestId: id, requestType: type, reason: 'REPLY_TIMEOUT', ...pendingTraceDetails() });
        failure();
      }
    }, timeoutMs);
    const payload = { type, context, inspectorId, requestId: id };
    if (changes) payload.changes = changes;
    if (token !== undefined) payload.token = token;
    try {
      // The host routes the PI envelope by its registered UUID; payload.context remains the action context.
      socket.send(JSON.stringify({ event: 'sendToPlugin', action, context: transportContext, payload }));
      if (type === 'canvas:hello') connection.helloSent = true;
      if (type === 'canvas:claim') connection.claimSent = true;
      observeConnection(type === 'canvas:hello' ? 'HELLO_SENT' : type === 'canvas:claim' ? 'CLAIM_SENT' : 'EDIT_SENT');
      trace(type === 'canvas:hello' ? 'PI_HELLO_SENT' : type === 'canvas:claim' ? 'PI_CLAIM_SENT' : 'EDIT_SENT', {
        requestId: id, requestType: type, fields: Object.keys(changes ?? {}),
        executable: changes?.executable, cwd: changes?.cwd,
      });
    } catch {
      trace('EDIT_SEND_FAILED', { requestId: id, requestType: type, reason: 'TRANSPORT_FAILED', ...pendingTraceDetails() });
      if (replyTimer !== undefined) clearTimer(replyTimer);
      replyTimer = undefined;
      open = false;
      latestRequest.active = false;
      connectionError('REQUEST_SEND_FAILED');
      failure();
    }
  }

  function flush() {
    if (debounceTimer !== undefined) clearTimer(debounceTimer);
    debounceTimer = undefined;
    if (!open || !ready || !pending) {
      if (pending) trace('EDIT_QUEUED', { reason: !open ? 'SOCKET_NOT_OPEN' : 'INSPECTOR_NOT_READY', ...pendingTraceDetails() });
      return;
    }
    const changes = {};
    for (const key of protectedFields()) changes[key] = dirtyValues.get(key);
    pending = false;
    if (Object.keys(changes).length > 0) sendRequest('canvas:edit', changes);
  }

  function edit(changes, { immediate = false } = {}) {
    let edit;
    // Check Timer metadata descriptors before JSON copying, without reading accessors.
    // Timer edits require a recognized current SDK binding, never a remembered UUID.
    try {
      const interval = Object.getOwnPropertyDescriptor(changes, 'intervalSeconds');
      if (interval) {
        if (!bindingValid || action !== TIMER_ACTION_UUID) { failure('INVALID_SETTINGS'); return false; }
        if (!Object.hasOwn(interval, 'value') || !Number.isSafeInteger(interval.value)
          || interval.value < MIN_INTERVAL_SECONDS || interval.value > MAX_INTERVAL_SECONDS) {
          failure('INTERVAL_INVALID'); return false;
        }
      }
      const policy = Object.getOwnPropertyDescriptor(changes, 'actionOnPress');
      if (policy) {
        if (!bindingValid || action !== TIMER_ACTION_UUID) { failure('INVALID_SETTINGS'); return false; }
        if (!Object.hasOwn(policy, 'value') || (policy.value !== 'refresh' && policy.value !== 'stop')) {
          failure('ACTION_ON_PRESS_INVALID'); return false;
        }
      }
    } catch { failure('INVALID_SETTINGS'); return false; }
    try { edit = copyRunSettings(changes); } catch {
      trace('EDIT_REJECTED', { reason: 'INVALID_SETTINGS' });
      failure('INVALID_SETTINGS'); return false;
    }
    if (Object.keys(edit).length === 0) { trace('EDIT_REJECTED', { reason: 'EMPTY_EDIT' }); return false; }
    for (const [key, value] of Object.entries(edit)) {
      if (key === 'actionOnPress' && bindingValid && action === TIMER_ACTION_UUID) {
        if (value !== 'refresh' && value !== 'stop') { failure('ACTION_ON_PRESS_INVALID'); return false; }
        continue;
      }
      if (key === 'intervalSeconds' && bindingValid && action === TIMER_ACTION_UUID) {
        if (!Number.isSafeInteger(value) || value < MIN_INTERVAL_SECONDS || value > MAX_INTERVAL_SECONDS) {
          failure('INTERVAL_INVALID'); return false;
        }
        continue;
      }
      if (key === 'themeColor') {
        try { edit.themeColor = normalizeThemeColor(value); } catch {
          trace('EDIT_REJECTED', { reason: 'THEME_COLOR_INVALID', fields: ['themeColor'] });
          failure('THEME_COLOR_INVALID');
          return false;
        }
        continue;
      }
      if (!FIELDS.has(key) || typeof value !== 'string' || value.includes('\0')) {
        trace('EDIT_REJECTED', {
          reason: !FIELDS.has(key) ? 'UNKNOWN_FIELD' : typeof value !== 'string' ? 'INVALID_FIELD_TYPE' : 'NUL_IN_FIELD',
          fields: [FIELDS.has(key) ? key : 'other'], executable: edit.executable, cwd: edit.cwd,
        });
        failure(key === 'argsText' ? 'ARGS_TEXT_INVALID' : key === 'cwd' ? 'INVALID_CWD'
          : key === 'executable' ? 'INVALID_EXECUTABLE' : 'INVALID_SETTINGS');
        return false;
      }
      if (key === 'executable' && !value.startsWith('/')) {
        trace('EDIT_REJECTED', { reason: 'EXECUTABLE_NOT_ABSOLUTE', fields: ['executable'], executable: value });
        failure('INVALID_EXECUTABLE');
        return false;
      }
    }
    let changed = false;
    for (const [key, value] of Object.entries(edit)) {
      if ((key === 'themeColor' || key === 'intervalSeconds' || key === 'actionOnPress') && dirtyValues.get(key) === value) continue;
      versions.set(key, (versions.get(key) ?? 0) + 1);
      dirtyValues.set(key, value);
      changed = true;
    }
    if (!changed) return true;
    pending = true;
    observeConnection();
    trace('EDIT_ACCEPTED', { fields: Object.keys(edit), executable: edit.executable, cwd: edit.cwd });
    if ((!open || !ready) && !immediate) trace('EDIT_QUEUED', {
      reason: !open ? 'SOCKET_NOT_OPEN' : 'INSPECTOR_NOT_READY', ...pendingTraceDetails(),
    });
    onStatus('saving');
    if (immediate) flush();
    else {
      if (debounceTimer !== undefined) clearTimer(debounceTimer);
      debounceTimer = setTimer(flush, delayMs);
    }
    return true;
  }

  function receive(message) {
    if (message?.event !== 'sendToPropertyInspector') return;
    const payload = message.payload;
    if (!payload || payload.type !== 'canvas:reply' || payload.context !== context
      || payload.inspectorId !== inspectorId || payload.requestId !== latestRequest?.id || !latestRequest.active) {
      trace('PI_REPLY_IGNORED', {
        payloadContext: payload?.context, replyInspectorId: payload?.inspectorId, replyRequestId: payload?.requestId,
        status: payload?.status,
        reason: !payload || payload.type !== 'canvas:reply' ? 'UNKNOWN_REPLY_TYPE'
          : payload.context !== context ? 'FOREIGN_CONTEXT'
            : payload.inspectorId !== inspectorId ? 'FOREIGN_INSPECTOR'
              : payload.requestId !== latestRequest?.id ? 'STALE_REQUEST' : 'EXPIRED_REQUEST',
      });
      observeConnection();
      return;
    }
    trace('PI_REPLY_RECEIVED', {
      payloadContext: payload.context, replyInspectorId: payload.inspectorId, replyRequestId: payload.requestId,
      status: payload.status, executable: traceProperty(payload.settings, 'executable'), cwd: traceProperty(payload.settings, 'cwd'),
    });
    const request = latestRequest;
    const version = connectionVersion;
    request.active = false;
    if (replyTimer !== undefined) clearTimer(replyTimer);
    replyTimer = undefined;
    if (payload.status === 'challenge' && request.type === 'canvas:hello' && typeof payload.token === 'string') {
      connection.challengeReceived = true;
      observeConnection('CHALLENGE_RECEIVED');
      trace('PI_CHALLENGE_RECEIVED', { requestId: request.id, requestType: request.type });
      if (!hydrate(payload.settings)) { connectionError('CHALLENGE_HYDRATION_FAILED'); return; }
      if (version !== connectionVersion) return;
      sendRequest('canvas:claim', undefined, payload.token);
      return;
    }
    if (payload.status !== 'saved') {
      connectionError('REPLY_NOT_CONFIRMED');
      trace('PI_REPLY_REJECTED', { status: payload.status, reason: SAFE_REASONS.has(payload.diagnosticCode) ? payload.diagnosticCode : 'UNCONFIRMED_REPLY' });
      failure(payload.status === 'error' ? payload.diagnosticCode : 'STATE_SAVE_FAILED');
      return;
    }
    if (request.type !== 'canvas:claim' && request.type !== 'canvas:edit') { connectionError('UNEXPECTED_REPLY_KIND'); failure(); return; }
    let settings;
    try { settings = copyRunSettings(payload.settings); } catch { connectionError('INVALID_REPLY_SETTINGS'); failure(); return; }
    for (const key of request.fields) {
      const fieldVersion = request.versions.get(key);
      if (versions.get(key) === fieldVersion) {
        acknowledged.set(key, fieldVersion);
        dirtyValues.delete(key);
      }
    }
    if (request.type === 'canvas:claim') {
      ready = true;
      observeConnection('READY');
      trace('PI_READY', { requestId: request.id, requestType: request.type, ...pendingTraceDetails() });
    }
    onStatus(protectedFields().size === 0 ? 'saved' : 'saving');
    hydrate(settings);
    if (version === connectionVersion && ready && pending) flush();
    observeConnection();
  }

  function disconnect() {
    trace('PI_DISCONNECT', pendingTraceDetails());
    connectionVersion++;
    open = false;
    ready = false;
    bindingValid = false;
    clearTimers();
    const previous = socket;
    socket = undefined;
    transportContext = undefined;
    try { previous?.close(); } catch {}
    observeConnection('DISCONNECTED');
  }

  function connect(port, propertyInspectorUUID, registerEvent, _info, actionInfoText) {
    connection.callbackCount++;
    connection.callbackArgCount = arguments.length;
    connection.callbackTypes = {
      port: connectionArgumentType(port), propertyInspectorUUID: connectionArgumentType(propertyInspectorUUID),
      registerEvent: connectionArgumentType(registerEvent), info: connectionArgumentType(_info), actionInfo: connectionArgumentType(actionInfoText),
    };
    connection.validation = 'PENDING';
    bindingValid = false;
    connection.registrationUuid = connectionText(propertyInspectorUUID);
    connection.registrationEvent = connectionText(registerEvent);
    connection.registrationSent = connection.helloSent = connection.challengeReceived = connection.claimSent = false;
    connection.socketUrl = null;
    observeConnection('SDK_CALLBACK_RECEIVED');
    disconnect();
    inspectorId = connectionCount++ === 0 ? inspectorIdPrefix : `${inspectorIdPrefix}.${connectionCount}`;
    if (hasBoundContext) {
      if (pending || dirtyValues.size > 0) trace('EDIT_DROPPED_ON_CONNECT', { reason: 'CONNECTION_RESET', ...pendingTraceDetails() });
      versions.clear();
      acknowledged.clear();
      dirtyValues.clear();
      pending = false;
    } else if (pending || dirtyValues.size > 0) {
      // Until a valid SDK callback identifies this PI, accepted edits must protect the controls from old settings.
      trace('EDIT_QUEUED', { reason: 'FIRST_CONNECTION_EDIT_RETAINED', ...pendingTraceDetails() });
    }
    latestRequest = undefined;
    requestId = 0;
    const version = connectionVersion;
    let step = 'ACTION_INFO_JSON';
    try {
      const info = JSON.parse(actionInfoText);
      const number = Number(port);
      step = 'SDK_PARAMETERS';
      if (!Number.isInteger(number) || number < 1 || number > 65535
        || typeof propertyInspectorUUID !== 'string' || typeof registerEvent !== 'string'
        || typeof info?.context !== 'string' || typeof info?.action !== 'string') throw new Error();
      // Parsing/parameter failure is not a binding. Once identity is valid, later calls are session resets,
      // even if hydration or socket creation subsequently fails; edits cannot migrate to another key.
      hasBoundContext = true;
      context = info.context;
      action = info.action;
      bindingValid = info.context.length > 0
        && (action === RUN_ACTION_UUID || action === TIMER_ACTION_UUID || action === ONCE_ACTION_UUID);
      transportContext = propertyInspectorUUID;
      const binding = { context, inspectorId };
      // Bind unassociated diagnostics before hydration/socket creation can fail. Keep their original
      // traceId, version, and inspectorId; a later key/session must drop them, not relabel them.
      for (const record of traceQueue) {
        if (!traceBindings.has(record)) {
          traceBindings.set(record, binding);
          if (!record.context) record.context = context;
        }
      }
      traceScope = binding;
      connection.validation = 'VALID';
      observeConnection('SDK_CALLBACK_VALIDATED');
      for (let index = traceQueue.length - 1; index >= 0; index--) {
        const record = traceQueue[index];
        if (traceBindings.get(record) !== traceScope || (record.context && record.context !== context)) {
          traceQueue.splice(index, 1); droppedTraces++;
        }
      }
      trace('PI_CONNECT', {
        executable: traceProperty(info.payload?.settings, 'executable'), cwd: traceProperty(info.payload?.settings, 'cwd'),
      });
      if (!hydrate(info.payload?.settings ?? {})) {
        connection.validation = 'HYDRATION_FAILED';
        connectionError('INITIAL_HYDRATION_FAILED');
        return;
      }
      step = 'SOCKET_CONSTRUCTION';
      connection.socketUrl = `ws://127.0.0.1:${number}`;
      socket = createSocket(`ws://127.0.0.1:${number}`);
      const connectedSocket = socket;
      observeConnection('SOCKET_CREATED');
      socket.onopen = () => {
        if (version !== connectionVersion) return;
        observeConnection('SOCKET_OPEN');
        try {
          connectedSocket.send(JSON.stringify({ event: registerEvent, uuid: propertyInspectorUUID }));
          connection.registrationSent = true;
          observeConnection('REGISTRATION_SENT');
          open = true;
          sendRequest('canvas:hello');
          flush();
          trace('PI_SOCKET_OPEN');
          if (droppedTraces > 0) {
            const count = droppedTraces;
            droppedTraces = 0;
            trace('PI_TRACE_DROPPED', { count, reason: 'BUFFER_OVERFLOW_OR_FOREIGN_CONTEXT' });
          }
        } catch { connectionError('REGISTRATION_OR_OPEN_HANDLER_FAILED'); failure(); }
      };
      socket.onmessage = event => {
        if (version !== connectionVersion || !open) return;
        try { receive(JSON.parse(event.data)); } catch { connectionError('INVALID_SOCKET_MESSAGE'); failure(); }
      };
      socket.onerror = socket.onclose = event => {
        if (version !== connectionVersion) return;
        open = false;
        ready = false;
        if (latestRequest) latestRequest.active = false;
        clearTimers();
        if (event?.type === 'close') {
          connection.lastClose = {
            code: Number.isInteger(event.code) ? event.code : null,
            wasClean: typeof event.wasClean === 'boolean' ? event.wasClean : null, version,
          };
        }
        connectionError(event?.type === 'error' ? 'WEBSOCKET_ERROR' : 'WEBSOCKET_CLOSED');
        trace(event?.type === 'error' ? 'PI_SOCKET_ERROR' : 'PI_SOCKET_CLOSED', { reason: 'TRANSPORT_UNAVAILABLE', ...pendingTraceDetails() });
        failure();
      };
    } catch {
      connection.validation = step === 'ACTION_INFO_JSON' ? 'INVALID_JSON' : step === 'SDK_PARAMETERS' ? 'INVALID_PARAMETERS' : connection.validation;
      connectionError(step === 'ACTION_INFO_JSON' ? 'ACTION_INFO_JSON_INVALID'
        : step === 'SDK_PARAMETERS' ? 'SDK_CALLBACK_PARAMETERS_INVALID' : 'SOCKET_CONSTRUCTION_FAILED');
      failure();
    }
  }

  return { connect, edit, flush, disconnect, hydrate, trace, getConnectionState };
}
