import { quote, split } from 'shlex';

function invalidArguments(diagnosticCode) {
  const error = new Error('Invalid arguments.');
  error.diagnosticCode = diagnosticCode;
  return error;
}

function copyArguments(input) {
  if (!Array.isArray(input)) throw invalidArguments('INVALID_ARGUMENT');

  const args = [];
  const length = Object.getOwnPropertyDescriptor(input, 'length').value;
  for (let index = 0; index < length; index++) {
    const descriptor = Object.getOwnPropertyDescriptor(input, String(index));
    if (!descriptor || !Object.hasOwn(descriptor, 'value')) {
      throw invalidArguments('INVALID_ARGUMENT');
    }
    const argument = descriptor.value;
    if (typeof argument !== 'string' || argument.includes('\0')) {
      throw invalidArguments('INVALID_ARGUMENT');
    }
    args.push(argument);
  }
  return args;
}

/** Parse plain argument text using shlex syntax, without execution or expansion. */
export function parseArguments(text) {
  try {
    if (typeof text !== 'string' || text.includes('\0')) {
      throw invalidArguments('ARGS_TEXT_INVALID');
    }
    if (text.trim() === '') return [];
    return copyArguments(split(text));
  } catch {
    // Never expose parser exceptions or incomplete input; callers must fix the text.
    throw invalidArguments('ARGS_TEXT_INVALID');
  }
}

function quoteEditorArgument(argument) {
  if (!/[\r\n]/.test(argument)) return quote(argument);
  const escaped = argument.replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\r/g, '\\r')
    .replace(/\n/g, '\\n');
  return `$'${escaped}'`;
}

/** Stock shlex quoting, with ANSI-C escapes for line breaks a single-line input would strip. */
export function serializeArguments(argv) {
  try {
    return copyArguments(argv).map(quoteEditorArgument).join(' ');
  } catch {
    throw invalidArguments('INVALID_ARGUMENT');
  }
}
